<script setup lang="ts">
import{computed,defineAsyncComponent,onMounted,ref}from"vue";import{InfoFilled,RefreshRight}from"@element-plus/icons-vue";import{fetchGenreContribution,type GenrePayload}from"../api/genreContribution";import{useThemeStore}from"../stores/theme";const Chart=defineAsyncComponent(()=>import("../components/ContentRankingChart.vue")),theme=useThemeStore(),data=ref<GenrePayload|null>(null),periodEnd=ref(""),genre=ref("TH"),metric=ref("play_vv"),loading=ref(false),error=ref(""),drawer=ref(false),nf=new Intl.NumberFormat("zh-CN");const num=(v:number|null|undefined)=>v==null?"--":nf.format(v),pct=(v:number|null|undefined)=>v==null?"--":`${(v*100).toFixed(2)}%`;async function load(){loading.value=true;error.value="";try{data.value=await fetchGenreContribution({period_end:periodEnd.value||undefined,genre_code:genre.value,metric:metric.value});if(!periodEnd.value&&data.value.summary)periodEnd.value=data.value.summary.period_end;if(data.value.summary)genre.value=data.value.summary.genre_code}catch(e){error.value="剧种内容贡献加载失败。";console.error(e)}finally{loading.value=false}}const colors=computed(()=>[theme.current.primary,"#42a5a5","#e3a64c","#8c72c7","#dd7185","#5d87c7","#9aab66"]),pieOption=computed(()=>({color:colors.value,tooltip:{trigger:"item",formatter:"{b}<br/>播放VV：{c}<br/>占比：{d}%"},legend:{bottom:0},series:[{type:"pie",radius:["42%","70%"],center:["50%","44%"],label:{formatter:"{b} {d}%"},data:(data.value?.distribution??[]).map(x=>({name:x.genre,value:x.play_vv}))}]}));onMounted(load)
</script>
<template><main class="main-content page-stack"><header class="page-intro"><div><h2>剧种内容贡献</h2><p>先看剧种播放结构，再查看单个剧种内部的内容贡献。</p></div><button class="source-button" @click="drawer=true"><el-icon><InfoFilled/></el-icon>数据说明</button></header><section class="filter-bar ranking-filter"><label><span>统计周期</span><el-select v-model="periodEnd" @change="load"><el-option v-for="p in data?.periods" :key="p.start+'|'+p.end" :label="`${p.start} 至 ${p.end}`" :value="p.end"/></el-select></label><label><span>剧种</span><el-select v-model="genre" @change="load"><el-option v-for="x in data?.distribution" :key="x.genre_code" :label="x.genre" :value="x.genre_code"/></el-select></label><div class="ranking-tabs"><button :class="{active:metric==='play_vv'}" @click="metric='play_vv';load()">播放VV</button><button :class="{active:metric==='play_uv'}" @click="metric='play_uv';load()">播放UV</button></div><el-button type="primary" :loading="loading" @click="load"><el-icon><RefreshRight/></el-icon>更新视图</el-button><div class="freshness"><span class="status-dot"></span><div><b>真实剧种数据</b><small>{{data?.meta.component??'--'}}</small></div></div></section><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><section class="ranking-summary-grid"><article class="metric-item"><div class="metric-label"><span>{{data?.summary?.genre??'--'}}播放VV</span><small>剧种汇总</small></div><strong>{{num(data?.summary?.total_play_vv)}}</strong></article><article class="metric-item"><div class="metric-label"><span>播放VV占全站</span><small>同周期剧种结构</small></div><strong>{{pct(data?.summary?.share)}}</strong></article><article class="metric-item"><div class="metric-label"><span>Top1 内容贡献率</span><small>Top1 VV ÷ 剧种VV</small></div><strong>{{pct(data?.summary?.top1_contribution)}}</strong></article><article class="metric-item"><div class="metric-label"><span>Top5 内容贡献率</span><small>Top5 VV ÷ 剧种VV</small></div><strong>{{pct(data?.summary?.top5_contribution)}}</strong></article></section><section class="panel"><div class="panel-head"><div><h2>剧种播放结构</h2><p>全部剧种 · 按播放VV</p></div></div><Chart v-if="data?.distribution.length" class="ranking-chart genre-chart" :option="pieOption"/></section><section class="panel ranking-detail-panel"><div class="panel-head"><div><h2>{{data?.summary?.genre??'--'}} · 内容 Top30</h2><p>{{metric==='play_vv'?'按播放VV':'按播放UV'}}排序</p></div><strong>{{data?.items.length??0}} 条</strong></div><div v-loading="loading" class="table-wrap"><table class="client-table ranking-table"><thead><tr><th>排名</th><th>内容名称</th><th>播放VV</th><th>播放UV</th><th>剧种内贡献率</th><th>内容类型</th><th>题材标签</th><th>产地</th></tr></thead><tbody><tr v-for="x in data?.items" :key="x.season_id"><td><span class="rank-badge">{{x.rank}}</span></td><td class="ranking-title"><strong>{{x.title}}</strong><small>ID {{x.season_id}}</small></td><td>{{num(x.play_vv)}}</td><td>{{num(x.play_uv)}}</td><td>{{pct(x.contribution)}}</td><td>{{x.content_type??'--'}}</td><td class="genre-cell">{{x.topic_tags??'--'}}</td><td>{{x.producer_region??'--'}}</td></tr></tbody></table></div></section><el-drawer v-model="drawer" title="剧种内容贡献来源与口径" size="440px"><div class="source-drawer"><section><span>数据源</span><strong>{{data?.meta.source??'--'}}</strong></section><section><span>接口</span><strong>{{data?.meta.component??'--'}}</strong></section><section><span>原始字段</span><div class="field-tags"><code v-for="f in data?.meta.original_fields" :key="f">{{f}}</code></div></section><p>{{data?.meta.limitation}}</p></div></el-drawer></main></template>
